-- TOC entry 609 (class 1255 OID 65610)
-- Name: get_professional_reviews_details(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_professional_reviews_details(prof_id uuid) RETURNS TABLE(id uuid, rating_punctuality integer, rating_didactics integer, rating_knowledge integer, rating_monitoring integer, comment text, created_at timestamp with time zone, client_name text, client_avatar text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        r.id,
        r.rating_punctuality,
        r.rating_didactics,
        r.rating_knowledge,
        r.rating_monitoring,
        r.comment,
        r.created_at,
        p.full_name as client_name,
        p.avatar_url as client_avatar
    FROM public.professional_reviews r
    JOIN public.profiles p ON r.client_id = p.id
    WHERE r.professional_id = prof_id
    ORDER BY r.created_at DESC;
END;
$$;


ALTER FUNCTION public.get_professional_reviews_details(prof_id uuid) OWNER TO postgres;

--
-- TOC entry 450 (class 1255 OID 29941)
-- Name: get_rank_title(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_rank_title(level integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF level <= 5 THEN RETURN 'Novato de Sofá';
    ELSIF level <= 10 THEN RETURN 'Caminhante de Fim de Semana';
    ELSIF level <= 20 THEN RETURN 'Rato de Academia';
    ELSIF level <= 30 THEN RETURN 'Maratonista de Dados';
    ELSIF level <= 50 THEN RETURN 'Ciborgue Fitness';
    ELSE RETURN 'Lenda Viva';
    END IF;
END;
$$;


ALTER FUNCTION public.get_rank_title(level integer) OWNER TO postgres;

